package com.narudzbine.identity.infrastructure.web;
import com.narudzbine.identity.api.*;
import com.narudzbine.identity.application.*;
import com.narudzbine.organizations.api.*;
import com.narudzbine.reporting.api.PlatformSummary;
import com.narudzbine.shared.api.ResourceRevisions;
import jakarta.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.bind.annotation.*;

@RestController
@ConditionalOnProperty(name="identity.http.enabled",havingValue="true")
public final class AdministrativeDirectoryController {
 private final AdministrativeOrganizations organizations;private final PlatformSummary summary;private final MemberService members;private final SessionService sessions;private final SessionTransportPolicy policy;private final LoginThrottle throttle;private final ResourceRevisions revisions;private final AccountRevisions accounts;private final Clock clock;private final TransactionTemplate tx;
 AdministrativeDirectoryController(AdministrativeOrganizations organizations,PlatformSummary summary,MemberService members,SessionService sessions,SessionTransportPolicy policy,LoginThrottle throttle,ResourceRevisions revisions,AccountRevisions accounts,Clock clock,PlatformTransactionManager manager){this.organizations=organizations;this.summary=summary;this.members=members;this.sessions=sessions;this.policy=policy;this.throttle=throttle;this.revisions=revisions;this.accounts=accounts;this.clock=clock;tx=new TransactionTemplate(manager);tx.setTimeout(10);}
 @GetMapping("/api/v1/admin/organizations") Page list(HttpServletRequest r){AuthController.noBody(r);var q=AdministrativeDirectoryRequests.query(r);var s=policy.select(r);admit(s,false);return tx.execute(status->{platform(s);var page=organizations.list(q);activity(s);return new Page(page.items().stream().map(i->OrganizationResponses.response(i,revisions)).toList(),q.page(),q.size(),page.total());});}
 @GetMapping("/api/v1/admin/organizations/{organizationId}") OrganizationController.Result get(@PathVariable String organizationId,HttpServletRequest r){AuthController.noQuery(r);AuthController.noBody(r);UUID org=id(organizationId,"organizationId");var s=policy.select(r);admit(s,false);return tx.execute(status->{platformTarget(s,org);var item=organizations.read(org);activity(s);return OrganizationResponses.response(item,revisions);});}
 @PutMapping("/api/v1/admin/organizations/{organizationId}") OrganizationController.Result correct(@PathVariable String organizationId,HttpServletRequest r)throws IOException{AuthController.noQuery(r);UUID org=id(organizationId,"organizationId");var input=AdministrativeDirectoryRequests.correction(r);var s=policy.select(r);String csrf=csrf(s,r);admit(s,true);return tx.execute(status->{var actor=platformTarget(s,org);checkCsrf(s,csrf);var old=organizations.read(org);if(!revisions.matches("organization/v1",org,old.revision(),input.revision()))throw new RevisionConflict(revisions.encode("organization/v1",org,old.revision()));if(input.values().address().country()!=old.country())throw new AuthHttpFailure(422,"VALIDATION_FAILED","/registeredAddress/country");var item=organizations.correct(actor.accountId(),org,input.values(),input.reason());activity(s);return OrganizationResponses.response(item,revisions);});}
 @GetMapping("/api/v1/admin/summary") Summary summary(HttpServletRequest r){AuthController.noQuery(r);AuthController.noBody(r);var s=policy.select(r);admit(s,false);return tx.execute(status->{platform(s);var rows=summary.read();String at=AccountResponses.time(clock.instant().truncatedTo(ChronoUnit.MILLIS));activity(s);return new Summary(at,rows);});}
 @GetMapping("/api/v1/admin/organizations/{organizationId}/members") MemberController.Page members(@PathVariable String organizationId,HttpServletRequest r){AuthController.noBody(r);UUID org=id(organizationId,"organizationId");var q=MemberRequests.query(r);var s=policy.select(r);admit(s,false);return tx.execute(status->{platformTarget(s,org);organizations.read(org);var page=members.list(org,q.page(),q.size(),q.state(),q.role(),q.total());activity(s);return new MemberController.Page(page.items().stream().map(this::member).toList(),q.page(),q.size(),page.total());});}
 @PostMapping("/api/v1/admin/organizations/{organizationId}/members/{accountId}/{action:deactivation|reactivation}") AccountResponses.Account staff(@PathVariable String organizationId,@PathVariable String accountId,@PathVariable String action,HttpServletRequest r)throws IOException{AuthController.noQuery(r);UUID org=id(organizationId,"organizationId"),target=id(accountId,"accountId");var input=AdministrativeDirectoryRequests.staff(r);var s=policy.select(r);String csrf=csrf(s,r);admit(s,true);return tx.execute(status->{var actor=sessions.authenticateForAdministrativeMemberWrite(s.secret(),s.transport(),org,target);checkCsrf(s,csrf);organizations.read(org);var item=members.changeAdministrative(actor.accountId(),org,target,input.revision(),action.equals("deactivation")?MemberService.Action.DEACTIVATE:MemberService.Action.REACTIVATE,input.reason());activity(s);return member(item);});}
 @PostMapping("/api/v1/admin/organizations/{organizationId}/{action:suspend|reactivate}") OrganizationController.Result state(@PathVariable String organizationId,@PathVariable String action,HttpServletRequest r)throws IOException{AuthController.noQuery(r);UUID org=id(organizationId,"organizationId");var input=AdministrativeDirectoryRequests.staff(r);var s=policy.select(r);String csrf=csrf(s,r);admit(s,true);return tx.execute(status->{var actor=sessions.authenticateForAdministrativeStateWrite(s.secret(),s.transport(),org);checkCsrf(s,csrf);var old=organizations.read(org);if(!revisions.matches("organization/v1",org,old.revision(),input.revision()))throw new RevisionConflict(revisions.encode("organization/v1",org,old.revision()));boolean active=action.equals("reactivate");var item=organizations.state(actor.accountId(),org,active,input.reason());if(!active&&!old.state().equals(item.state()))sessions.revokeOrganizationSessions(org);activity(s);return OrganizationResponses.response(item,revisions);});}
 private com.narudzbine.identity.api.AuthenticatedSession platformTarget(SessionTransportPolicy.Selected s,UUID org){return sessions.authenticateForAdministrativeOrganizationWrite(s.secret(),s.transport(),org);}
 private com.narudzbine.identity.api.AuthenticatedSession platform(SessionTransportPolicy.Selected s){var p=sessions.authenticateForProfileWrite(s.secret(),s.transport());if(!p.platformAdministrator())throw new AuthHttpFailure(404,"NOT_FOUND");return p;}
 private void admit(SessionTransportPolicy.Selected s,boolean write){UUID actor=tx.execute(status->sessions.replayAdmissionAccount(s.secret(),s.transport()));throttle.admitApi(actor,write);if(!Boolean.TRUE.equals(tx.execute(status->sessions.isPlatformAccount(actor))))throw new AuthHttpFailure(404,"NOT_FOUND");}
 private void activity(SessionTransportPolicy.Selected s){sessions.recordSuccessfulActivity(s.secret(),s.transport());}
 private void checkCsrf(SessionTransportPolicy.Selected s,String csrf){if(s.transport()==SessionTransport.BROWSER)sessions.requireCsrf(s.secret(),csrf);}
 private static String csrf(SessionTransportPolicy.Selected s,HttpServletRequest r){return s.transport()==SessionTransport.BROWSER?AuthController.csrfHeader(r):null;}
 private static UUID id(String v,String field){return ContactRequests.id(v,"PATH",field);}
 private AccountResponses.Account member(MemberService.Member m){return new AccountResponses.Account(m.id(),accounts.encode(m.id(),m.revision()),m.organizationId(),"BUSINESS",m.email(),m.displayName(),m.role().name(),m.state(),m.languageOverride(),m.homeLocationId(),AccountResponses.time(m.createdAt()),AccountResponses.time(m.updatedAt()));}
 record Page(List<OrganizationController.Result> items,int page,int size,Long total){}
 record Summary(String asOf,List<PlatformSummary.Country> countries){}
}
